124	// Always read the specified marketplace file from disk so installs see the
125	// latest marketplace.json contents without any in-memory cache invalidation.
126	pub fn resolve_marketplace_plugin(
127	    marketplace_path: &AbsolutePathBuf,
128	    plugin_name: &str,
129	) -> Result<ResolvedMarketplacePlugin, MarketplaceError> {
130	    let marketplace = load_marketplace(marketplace_path)?;
131	    let marketplace_name = marketplace.name;
132	    let plugin = marketplace
133	        .plugins
134	        .into_iter()
135	        .find(|plugin| plugin.name == plugin_name);
136	
137	    let Some(plugin) = plugin else {
138	        return Err(MarketplaceError::PluginNotFound {
139	            plugin_name: plugin_name.to_string(),
140	            marketplace_name,
141	        });
142	    };
143	
144	    let MarketplacePlugin {
145	        name,
146	        source,
147	        install_policy,
148	        auth_policy,
149	        ..
150	    } = plugin;
151	    if install_policy == Some(MarketplacePluginInstallPolicy::NotAvailable) {
152	        return Err(MarketplaceError::PluginNotAvailable {
153	            plugin_name: name,
154	            marketplace_name,
155	        });
156	    }
157	
158	    let plugin_id = PluginId::new(name, marketplace_name).map_err(|err| match err {
159	        PluginIdError::Invalid(message) => MarketplaceError::InvalidPlugin(message),
160	    })?;
161	    Ok(ResolvedMarketplacePlugin {
162	        plugin_id,
163	        source_path: resolve_plugin_source_path(marketplace_path, source)?,
164	        auth_policy,
165	    })
166	}
